ans = 0
for x in range(l + 1):
    max_y = l - x
    # Case 1: a + x is the largest
    # Need b + y + c + z > a + x
    # y + z > a + x - b - c
    t = a + x - b - c
    if t < 0:
        cnt = (max_y + 1) * (max_y + 2) // 2
    else:
        if t > max_y:
            cnt = 0
        else:
            cnt = (max_y + 1) * (max_y + 2) // 2 - (t + 1) * (t + 2) // 2
    ans += cnt

    # Case 2: b + y is the largest
    t = b + x - a - c
    if t < 0:
        cnt = (max_y + 1) * (max_y + 2) // 2
    else:
        if t > max_y:
            cnt = 0
        else:
            cnt = (max_y + 1) * (max_y + 2) // 2 - (t + 1) * (t + 2) // 2
    ans += cnt

    # Case 3: c + z is the largest
    t = c + x - a - b
    if t < 0:
        cnt = (max_y + 1) * (max_y + 2) // 2
    else:
        if t > max_y:
            cnt = 0
        else:
            cnt = (max_y + 1) * (max_y + 2) // 2 - (t + 1) * (t + 2) // 2
